      '// Canonical completed typed outcome data. Failure rows project to ordinary value sums through\n// Row<! E>; Result itself remains ordinary source-defined data with no runtime row descriptor.\n\npub struct Success<A> {\n  value: A\n}\n\npub struct Failure<F> {\n  error: F\n}\n\npub struct Result<A, F> {\n  value: Success<A> | Failure<F>\n}\n\npub fn succeed<A, F>(value: A) -> Result<A, F> {\n  return Result<A, F> { value: Success<A> { value: move value } }\n}\n\npub fn failResult<A, F>(error: F) -> Result<A, F> {\n  return Result<A, F> { value: Failure<F> { error: move error } }\n}\n',
